pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30 ether);
        Reverter actor = new Reverter();
        vm.deal(address(actor), amount);
        vm.prank(address(actor));
        c.deposit{value: amount}();
        bool ok;
        vm.prank(address(actor));
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // A failed payout must not consume the credit: it stays fully recoverable.
        assertTrue(!ok ? (c.credit(address(actor)) == amount && address(c).balance >= amount)
                        : (c.credit(address(actor)) == 0));
    }
}

contract Reverter {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}

