pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        Reverter actor = new Reverter();
        vm.deal(address(actor), amount);
        vm.prank(address(actor));
        c.deposit{value: amount}();
        uint256 balBefore = address(c).balance;
        vm.prank(address(actor));
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // General rule: withdrawAll either reverts with no ETH leaving the contract,
        // or succeeds having actually decreased address(c).balance by the credit.
        assertTrue(!ok ? (address(c).balance == balBefore)
                       : (address(c).balance == balBefore - amount),
            "withdrawAll must not report success without actually sending the funds");
    }
}

