pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < 1 ether);
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), amount);
        attacker.depositIntoC(amount);
        bool ok;
        try attacker.attack() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract ReentrantAttacker {
    C c;
    bool reentered;

    constructor(C _c) { c = _c; }

    function depositIntoC(uint256 amount) external {
        c.deposit{value: amount}();
    }

    function attack() external {
        c.withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawAll();
        }
    }
}

