pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, 100 ether);

        // ledger of what C should actually hold
        uint256 ledger = 0;

        // deposit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        ledger += amount;
        assertTrue(address(c).balance == ledger);

        // withdraw all
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        ledger = 0; // full credit was paid out

        // GENERAL RULE: after a full deposit/withdraw cycle, the contract holds
        // exactly the ledgered Ether (all deposited funds left the contract).
        assertTrue(ok && address(c).balance == ledger);
    }
}

