pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        // Admissible domain: the actor must be able to receive Ether, otherwise the
        // low-level call in withdrawAll legitimately fails and the reference reverts
        // (this is what made the previous, untightened rule fail on the reference).
        // A codeless address has no fallback, so receiving via plain call succeeds
        // and withdrawAll always completes.
        vm.assume(actor.code.length == 0);
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max / 2);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        c.withdrawAll();

        // General rule: after a completed deposit/withdraw cycle all deposited Ether
        // has left the contract, so its tracked ledger equals its real Ether balance.
        assertTrue(c.balance() == address(c).balance);
    }
}

